<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/auth.css"><div class="auth-page"><section class="auth-shell"><aside class="auth-intro"><p class="eyebrow">ACCOUNT RECOVERY</p><h1>กลับเข้าสู่บัญชีอย่างปลอดภัย</h1><p>เราจะส่งลิงก์แบบใช้ครั้งเดียวไปยังอีเมลที่ลงทะเบียนไว้ ลิงก์หมดอายุภายใน 30 นาที</p></aside><div class="auth-card"><header class="auth-heading"><h2>ลืมรหัสผ่าน</h2><p>กรอกอีเมลของบัญชี KitchenMart</p></header><div class="auth-error" id="authError" role="alert"><span></span></div><form class="auth-form" id="resetRequest"><div class="auth-field"><label for="email">อีเมล</label><div class="auth-input"><i class="fa-regular fa-envelope"></i><input id="email" type="email" name="email" required autocomplete="email"></div></div><input type="hidden" name="action" value="request"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><button class="btn btn-primary auth-submit">ส่งลิงก์ตั้งรหัสผ่าน</button></form><p class="auth-switch"><a href="<?php echo BASE_URL;?>login.php">กลับไปหน้าเข้าสู่ระบบ</a></p></div></section></div><script>document.getElementById('resetRequest').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),box=document.getElementById('authError');b.disabled=true;try{const r=await fetch(`${BASE_URL}api/password-reset.php`,{method:'POST',body:new FormData(f)}),j=await r.json();box.querySelector('span').textContent=j.message;box.classList.add('show');if(j.status==='success'){box.style.background='#eaf2ed';box.style.color='#173f32';f.reset()}}finally{b.disabled=false}};</script><?php require_once __DIR__.'/includes/footer.php';?>
